llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Limonin, a highly oxygenated polycyclic dilactone natural product, shows poor oral bioavailability in humans; the query shares a rigid, multiple-lactone, oxygen-rich scaffold, supporting a low F (<20%) outcome.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Artemisinin, a lactone-containing rigid natural product, has low oral bioavailability in humans; although the query is more polar with higher TPSA and lower logD, this supports a low-F direction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C50"],
      "claim": "EM574, a complex oxygenated macrolide, has very low oral bioavailability (~2%) due to extensive first-pass clearance, illustrating that complex oxygenated natural products can fall far below 20% F; transferability is limited by low structural similarity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Artesunate, an artemisinin derivative, achieved 61% absolute oral bioavailability in Thai patients, providing a contradictory high-F example; however, its ionizable succinate ester and higher solubility limit transfer to the neutral, highly polar query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "The query is a neutral, rigid, highly oxygenated polycyclic lactone with high TPSA and low logD, predicting poor passive permeability. The most relevant experimental analogues—limonin and artemisinin—show poor/low oral bioavailability in humans. High-F evidence comes from structurally dissimilar classes (macrolides, steroids, nucleosides) and does not transfer well. Therefore low F (<20%) is better supported, with low confidence due to low structural similarity and lack of direct data.",
  "evidence_gaps": [
    "No direct human or animal absolute bioavailability data for the query or a close structural analogue.",
    "Metabolic stability and first-pass clearance are unknown from structure alone.",
    "Qualitative 'low' or 'poor' bioavailability reports may not map precisely to the F<20% threshold.",
    "Potential transporter-mediated absorption or efflux is not characterized."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

